"""The one accessor for "what is on the board", across every lifecycle (#514).

Why this module exists
----------------------
`pipeline-state.json` is not the board on every lifecycle. Under `build_mode:
spq` it is stripped to a mode + identity POINTER at `open_cycle`, and the board
moves to `spq/cycles/<cycle-id>/execution-state.json` -- see
`spq_state_machine._write_state`, which strips the pointer deliberately so it
cannot become a stale second copy. Under the retired-but-still-readable v3.0
Multi-Spec layout the board is one slot per spec under `specs`.

So a consumer that opens `pipeline-state.json` and reads `current_stories` sees
**nothing on an SPQ project, without erroring**. That has now been an
independently-found defect in four separate readers:

    1. `conformance/drivers/hosts.py::read_story`
    2. `benchmarks/parallelism/pilot_metrics.py` -- printed 0 work units, 0
       dispatches, 0 delivery tokens and mean gate depth 0.0 on a real SPQ run
    3. `signals.py::harvest_pipeline_signals` -- emitted no recurring-failure
       MethodSignals on SPQ, the one lifecycle that invented MethodSignals
    4. `synaptory-session-start.sh` -- restored no pipeline context at all on
       an SPQ session

Every one of the four reported emptiness as a measurement. That is the whole
defect: the read does not fail, it succeeds against the wrong file.

The rule this module encodes
----------------------------
**A board that could not be read and a board that is empty must not share a
representation.** `read_board()` therefore always answers two questions, never
one: *is there a board here at all* (`available`, `problems`) and *what is on
it* (`stories`). A consumer that only unpacks `.stories` still gets the correct
list on all three lifecycles; a consumer that cares about the difference has
`available` and `problems` to read.

This is a CONSUMER-side accessor. The state machines and `story_pipeline` write
the state and already know every layout; they must not route through here (it
would be a cycle, and `spq_state_machine` is where the SPQ half is implemented).

Python 3.9 compatible: this file is projected into every host package.
"""

from __future__ import annotations

import json
import os
import sys
from typing import Any, Dict, List, Optional, Tuple

#: The layouts `read_board` can distinguish. `spq` means the pointer named
#: SPQ; `multi-spec` the retired v3.0 envelope; `flat` a v2 scrum/kanban board;
#: `none` no state file at all.
LAYOUTS = ("none", "flat", "multi-spec", "spq")

DEFAULT_BUILD_MODE = "scrum"

#: Why an SPQ project still on the retired v3.0 Multi-Spec envelope is reported
#: as UNREADABLE rather than as an empty pre-Commit Cycle.
#:
#: The predecessor's `spq_state_machine.read_state` refused such a pointer
#: outright, and `available=False` here was that refusal surfacing. The #644
#: rewrite made `read_state` return the default board whenever no Cycle
#: identity resolves -- correct for a genuinely fresh project, and wrong for
#: this one, whose pointer still carries `lifecycle_state` and `current_cycle`
#: from a layout nothing reads any more. So a project that HAD work read as a
#: Cycle that admitted nothing: the exact substitution -- emptiness reported as
#: a measurement -- that four independently-found defects made and that this
#: module exists to prevent.
#:
#: Detected on the POINTER's own shape rather than by asking the state machine,
#: because the state machine no longer distinguishes the two cases and this is
#: the consumer-side accessor whose entire contract is that it does. The same
#: condition is validated by `state_drift.validate_pipeline_state`, which turns
#: it into a session warning; both name `ADR-035`, because that is the decision
#: a reader arriving here has to find.
RETIRED_V3_REFUSAL = (
    "pipeline-state.json is on the retired v3.0 Multi-Spec layout while "
    "build_mode is spq, so no Cycle identity resolves from it and nothing here "
    "has read a board. There is no migrator: `ADR-035` refuses the old layout "
    "by name rather than converting it, because pilot state carried no audit "
    "value. Open a Cycle -- `open_cycle` writes the board at "
    ".synaptory/.orchestrator/spq/cycles/<cycle-id>/execution-state.json and "
    "leaves this file a mode+identity pointer"
)


def _is_retired_v3_envelope(pointer: Dict[str, Any]) -> bool:
    """Is this SPQ pointer still wrapped in the v3.0 Multi-Spec envelope?

    Two triggers, matching `state_drift`: the declared version, and the `specs`
    slot map. A live SPQ pointer is written at version `2.0` by
    `spq_state_machine._write_pointer` and carries no `specs` key at all, so
    neither trigger can fire on a healthy project.
    """
    return pointer.get("version") == "3.0" or isinstance(pointer.get("specs"), dict)


def state_path(project_dir: str) -> str:
    """`pipeline-state.json` -- the pointer, which is only sometimes the board."""
    return os.path.join(
        project_dir, ".synaptory", ".orchestrator", "pipeline-state.json"
    )


class Board(object):
    """What is on the board, plus whether a board could be read at all.

    Attributes:
        build_mode  `scrum` | `kanban` | `spq` (defaults to scrum, per the
                    documented config default, when the file names no mode).
        layout      one of `LAYOUTS`; the shape the board was found in.
        available   True when a board was located and parsed. False means the
                    read failed -- an absent file, unparseable JSON, or an SPQ
                    project still on the retired v3.0 envelope, which this
                    module refuses (`RETIRED_V3_REFUSAL`). `stories` is then
                    empty because NOTHING WAS READ, which is not the same fact
                    as an empty board.
        hydrated    SPQ only: True once a Cycle exists in this checkout. A
                    pre-COMMIT SPQ project is `available` and NOT `hydrated`,
                    and its empty board is correct rather than blind.
        stories     the work units / stories on the board, across every
                    substate (so multi-spec is not a second blind spot).
        substates   [(label, substate_dict)] -- one entry for a flat or SPQ
                    board, one per spec for multi-spec.
        identity    SPQ identity (`cycle_id`, `cycle_seq`, `workstream_id`),
                    empty on the other lifecycles.
        admitted_units  ids of the units admitted to the current Cycle. Equal
                    to the story ids on a delivery workstream; on an
                    INTEGRATION seat the board is empty by design and the
                    admitted ids live in `_integration_cycle_units`, so an
                    integration clone still names its units.
        cycles      the recorded per-Cycle history: one rollup per CLOSED
                    Cycle, in the order it was archived. Empty on a project
                    that has closed none, which `available` distinguishes from
                    a history that could not be read at all. See
                    `completed_cycles`.
        source      the file the board was actually read from.
        problems    why a read was not clean. Never silently empty on failure.
    """

    __slots__ = (
        "build_mode", "layout", "available", "hydrated", "stories",
        "substates", "identity", "admitted_units", "cycles", "source",
        "problems",
    )

    def __init__(
        self,
        build_mode: str = DEFAULT_BUILD_MODE,
        layout: str = "none",
        available: bool = False,
        hydrated: bool = False,
        stories: Optional[List[Dict[str, Any]]] = None,
        substates: Optional[List[Tuple[str, Dict[str, Any]]]] = None,
        identity: Optional[Dict[str, Any]] = None,
        admitted_units: Optional[List[str]] = None,
        cycles: Optional[List[Dict[str, Any]]] = None,
        source: str = "",
        problems: Optional[List[str]] = None,
    ) -> None:
        self.build_mode = build_mode
        self.layout = layout
        self.available = available
        self.hydrated = hydrated
        self.stories = stories if stories is not None else []
        self.substates = substates if substates is not None else []
        self.identity = identity if identity is not None else {}
        self.admitted_units = admitted_units if admitted_units is not None else []
        self.cycles = cycles if cycles is not None else []
        self.source = source
        self.problems = problems if problems is not None else []

    # -- convenience, so a consumer never re-derives these ------------------

    def completed_cycles(self) -> List[Dict[str, Any]]:
        """The recorded history of closed Cycles -- the `C-16` route (#646).

        WHY THIS EXISTS ON THE ACCESSOR AND NOT IN THE CONSUMER. Two rules
        collided, and both were right: `read_board` is the one sanctioned way to
        read pipeline state, and `Board` exposed no completed-Cycle history at
        all. So a throughput / cut-rate consumer -- which is what concurrency
        must be planned against -- had no route to its numbers that the board
        census permits, and would have been pushed straight back to the direct
        read four readers already acquired the same defect from. The
        conformance measurement probe hit it immediately and reported the gap as
        a stated problem rather than reading the file.

        An empty list means no Cycle has closed. That is an ABSENCE, and a
        caller must not read it as a history of zero throughput -- pair it with
        `available`, and see `cycle_measurement.history_report`, which is where
        the distinction is given a shape.
        """
        return list(self.cycles)

    @property
    def is_spq(self) -> bool:
        return self.build_mode == "spq"

    @property
    def lifecycle_state(self) -> str:
        """The lifecycle of the primary substate ('' when none was read)."""
        for _label, sub in self.substates:
            value = sub.get("lifecycle_state")
            if value:
                return str(value)
        return ""

    def done_count(self) -> int:
        return sum(1 for s in self.stories if s.get("state") == "done")

    def story_ids(self) -> List[str]:
        return [str(s.get("id")) for s in self.stories if s.get("id")]

    def as_dict(self) -> Dict[str, Any]:
        return {
            "build_mode": self.build_mode,
            "layout": self.layout,
            "available": self.available,
            "hydrated": self.hydrated,
            "lifecycle_state": self.lifecycle_state,
            "stories": self.stories,
            "story_ids": self.story_ids(),
            "done": self.done_count(),
            "identity": self.identity,
            "admitted_units": self.admitted_units,
            "cycles": self.cycles,
            "completed_cycles": len(self.cycles),
            "source": self.source,
            "problems": self.problems,
        }

    def __repr__(self) -> str:  # pragma: no cover - diagnostics
        return (
            "Board(build_mode=%r, layout=%r, available=%r, stories=%d, "
            "problems=%r)" % (
                self.build_mode, self.layout, self.available,
                len(self.stories), self.problems,
            )
        )


def _substate_stories(sub: Dict[str, Any]) -> List[Dict[str, Any]]:
    stories = sub.get("current_stories")
    if not isinstance(stories, list):
        return []
    return [s for s in stories if isinstance(s, dict)]


def _substate_cycles(sub: Dict[str, Any]) -> List[Dict[str, Any]]:
    """The closed-Cycle rollups one substate archived.

    `cycles_completed` is where every lifecycle's close archives its rollup, so
    the key is read the same way on all three layouts rather than special-cased
    for SPQ -- a per-layout reader here would be the second definition of the
    layout that this module exists to prevent.
    """
    recorded = sub.get("cycles_completed")
    if not isinstance(recorded, list):
        return []
    return [c for c in recorded if isinstance(c, dict)]


def cycles_in_state(state: Dict[str, Any]) -> List[Dict[str, Any]]:
    """Closed-Cycle history on an ALREADY-LOADED state dict, every layout.

    The `completed_cycles` counterpart to `stories_in_state`, for a caller
    holding a state the state machine just returned. Same limit: it cannot
    rescue an SPQ POINTER, because a pointer holds no history to find.
    """
    if not isinstance(state, dict):
        return []
    specs = state.get("specs")
    if isinstance(specs, dict):
        out: List[Dict[str, Any]] = []
        for sub in specs.values():
            if isinstance(sub, dict):
                out.extend(_substate_cycles(sub))
        return out
    return _substate_cycles(state)


def stories_in_state(state: Dict[str, Any]) -> List[Dict[str, Any]]:
    """Every story on an ALREADY-LOADED state dict, across every layout.

    For callers handed a state dict rather than a project directory (test
    injection, a state the state machine just returned). Covers the v3.0
    Multi-Spec envelope as well as a flat board, because reading only the
    top-level `current_stories` off a multi-spec file is the same defect one
    layout over. It cannot rescue an SPQ POINTER -- there are no stories in a
    pointer to find -- so a caller that can reach the project directory should
    use `read_board`, which can.
    """
    if not isinstance(state, dict):
        return []
    specs = state.get("specs")
    if isinstance(specs, dict):
        out: List[Dict[str, Any]] = []
        for sub in specs.values():
            if isinstance(sub, dict):
                out.extend(_substate_stories(sub))
        return out
    return _substate_stories(state)


def _spq_board(project_dir: str, pointer: Dict[str, Any]) -> Board:
    """The SPQ half: ask the state machine, which owns the layout.

    Deliberately delegated rather than re-derived. `spq_state_machine.read_state`
    already resolves identity (flag > env > pin > pointer), falls back to the
    pointer for a pre-Cycle lifecycle, and applies the Slice->Cycle read shim.
    Mirroring any of that here would create the second definition of the layout
    that this module exists to prevent.
    """
    if _is_retired_v3_envelope(pointer):
        return Board(
            build_mode="spq", layout="spq", available=False,
            source=state_path(project_dir),
            problems=[RETIRED_V3_REFUSAL],
        )
    sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
    try:
        import spq_state_machine as _spq
    except Exception as exc:  # pragma: no cover - projection accident
        return Board(
            build_mode="spq", layout="spq", available=False,
            source=state_path(project_dir),
            problems=["cannot import spq_state_machine: %s" % exc],
        )

    try:
        state = _spq.read_state(project_dir)
    except Exception as exc:  # noqa: BLE001 - a refusal is a problem, not a zero
        return Board(
            build_mode="spq", layout="spq", available=False,
            source=state_path(project_dir),
            problems=["SPQ board unreadable: %s" % exc],
        )

    ident = {
        "cycle_id": state.get("_cycle_id"),
        "cycle_seq": state.get("current_cycle"),
        "workstream_id": state.get("_workstream_id"),
    }
    stories = _substate_stories(state)
    admitted = [str(s.get("id")) for s in stories if s.get("id")]
    # An integration seat holds no units on its own board by design -- they live
    # on the delivery workstream boards -- so its admitted ids have to come from
    # somewhere else, or an integration clone cannot name its own Cycle's work.
    #
    # Two sources, and only the second is durable. `_integration_cycle_units` is
    # set by `open_cycle` but `_write_state` strips every underscore key, so it
    # exists only on the dict `open_cycle` returned and never on disk. The
    # SEALED MANIFEST is the durable record of what a Cycle admitted, so it is
    # what a resumed session can actually read. (That the state copy is
    # non-durable is a real gap, reported with #514 rather than fixed here:
    # writing it would mean changing `_write_state`, which is the SPQ state
    # machine's writer and not this ticket's lane.)
    if not admitted:
        admitted = [
            str(u) for u in (state.get("_integration_cycle_units") or []) if u
        ]
    # No integration seat any more: one Engineering Lead, one Crew, one board
    # (#644). The key stays on the identity dict, always False, because a
    # reader built against it should see "not a seat" rather than KeyError --
    # and because a seat is the thing that no longer exists, not a fact that
    # became unknowable.
    integration_seat = False
    if not admitted and state.get("_cycle_id"):
        try:
            manifest = _spq.read_manifest(project_dir, str(state["_cycle_id"]))
            admitted = [
                str(u.get("id")) for u in (manifest.get("admitted_units") or [])
                if isinstance(u, dict) and u.get("id")
            ]
        except Exception:  # pragma: no cover - an unsealed Cycle has none
            admitted = []
    hydrated = bool(state.get("_cycle_id"))
    source = state_path(project_dir)
    if hydrated:
        try:
            import spq_paths as _paths

            source = _paths.execution_state_path(
                project_dir, str(state["_cycle_id"])
            )
        except Exception:  # pragma: no cover - diagnostics only
            pass
    ident["integration_seat"] = integration_seat
    return Board(
        build_mode="spq",
        layout="spq",
        available=True,
        hydrated=hydrated,
        stories=stories,
        substates=[("", state)],
        identity=ident,
        admitted_units=admitted,
        cycles=_substate_cycles(state),
        source=source,
    )


def read_board(project_dir: str) -> Board:
    """The board for THIS project, whatever lifecycle it is on.

    Never raises: a consumer of pipeline state is usually a hook, a report or a
    metric, and none of those may take down the session. Failure is reported on
    the Board (`available=False` plus `problems`) instead of thrown, because the
    thing that must never happen is a failure that looks like an empty board.
    """
    path = state_path(project_dir)
    try:
        with open(path, "r", encoding="utf-8") as fh:
            raw = fh.read()
    except OSError as exc:
        return Board(
            layout="none", available=False, source=path,
            problems=["no pipeline-state.json: %s" % exc],
        )
    if not raw.strip():
        return Board(
            layout="none", available=False, source=path,
            problems=["pipeline-state.json is empty"],
        )
    try:
        state = json.loads(raw)
    except ValueError as exc:
        return Board(
            layout="none", available=False, source=path,
            problems=["pipeline-state.json is not valid JSON: %s" % exc],
        )
    if not isinstance(state, dict):
        return Board(
            layout="none", available=False, source=path,
            problems=["pipeline-state.json is not a JSON object"],
        )

    mode = str(state.get("build_mode") or DEFAULT_BUILD_MODE).strip().lower()

    if mode == "spq":
        return _spq_board(project_dir, state)

    specs = state.get("specs")
    if isinstance(specs, dict):
        # v3.0 Multi-Spec: every slot is a board. Rolling up ALL of them rather
        # than only `active_spec` is deliberate -- a consumer asking "what is on
        # the board" that sees only the active slot is the same defect one
        # layout over.
        substates: List[Tuple[str, Dict[str, Any]]] = []
        stories: List[Dict[str, Any]] = []
        problems: List[str] = []
        active = state.get("active_spec")
        if active is not None and active not in specs:
            problems.append(
                "active_spec %r has no matching entry in specs" % (active,)
            )
        ordered = sorted(specs, key=lambda sid: (sid != active, str(sid)))
        for sid in ordered:
            sub = specs[sid]
            if not isinstance(sub, dict):
                problems.append("spec %s: not an object" % sid)
                continue
            substates.append((str(sid), sub))
            stories.extend(_substate_stories(sub))
        return Board(
            build_mode=mode, layout="multi-spec", available=True, hydrated=True,
            stories=stories, substates=substates,
            identity={"active_spec": active if active in specs else None},
            admitted_units=[str(s.get("id")) for s in stories if s.get("id")],
            cycles=[c for _label, sub in substates for c in _substate_cycles(sub)],
            source=path, problems=problems,
        )

    stories = _substate_stories(state)
    return Board(
        build_mode=mode, layout="flat", available=True, hydrated=True,
        stories=stories, substates=[("", state)],
        admitted_units=[str(s.get("id")) for s in stories if s.get("id")],
        cycles=_substate_cycles(state),
        source=path,
    )


# ---------------------------------------------------------------------------
# Session-restore rendering
# ---------------------------------------------------------------------------
# Lives here rather than inline in a host hook so all three hosts render the
# same restore summary from the same code. `synaptory-session-start.sh` branched
# on `scrum` and `kanban` and stopped, so an SPQ session restored no pipeline
# context at all -- and the SPQ design's own resume rule (a resumed session runs
# `next_action` first and never replans from memory) is precisely the rule an
# orchestrator with no restored context is invited to break.


def _render_flat(mode: str, sub: Dict[str, Any], prefix: str = "") -> List[str]:
    lines = []
    lines.append("%sLifecycle State: %s" % (
        prefix, sub.get("lifecycle_state", "INCEPTION")))
    stories = _substate_stories(sub)
    if mode == "scrum":
        goal = sub.get("sprint_goal", "")
        done = sum(1 for s in stories if s.get("state") == "done")
        lines.append("%sCurrent Sprint: %s" % (prefix, sub.get("current_sprint", 0)))
        if goal:
            lines.append("%sSprint Goal: %s" % (prefix, goal))
        lines.append("%sCompleted Sprints: %d" % (
            prefix, len(sub.get("sprints_completed") or [])))
        if stories:
            lines.append("%sStories: %d/%d done" % (prefix, done, len(stories)))
    elif mode == "kanban":
        lines.append("%sCumulative Tickets: %s" % (
            prefix, sub.get("cumulative_ticket_number", 0)))
        lines.append("%sOn Board: %d" % (prefix, len(stories)))
        lines.append("%sCompleted: %d" % (
            prefix, len(sub.get("tickets_completed") or [])))
    return lines


def _render_spq(board: Board) -> List[str]:
    sub = board.substates[0][1] if board.substates else {}
    lines = ["Lifecycle State: %s" % (sub.get("lifecycle_state", "DISCOVERY"),)]
    cycle_seq = board.identity.get("cycle_seq") or 0
    cycle_id = board.identity.get("cycle_id")
    if board.hydrated and cycle_id:
        lines.append("Current Cycle: %s (%s)" % (cycle_seq, cycle_id))
    else:
        lines.append(
            "Current Cycle: none yet in this checkout "
            "(pre-COMMIT; no Cycle has been opened)"
        )
    goal = sub.get("cycle_goal")
    if goal:
        lines.append("Cycle Goal: %s" % goal)
    workstream = board.identity.get("workstream_id")
    if workstream:
        lines.append("Workstream: %s" % workstream)
    lines.append("Completed Cycles: %d" % len(board.cycles))
    if board.stories:
        lines.append("Work Units: %d/%d done" % (
            board.done_count(), len(board.stories)))
        for story in board.stories:
            lines.append("  - %s [%s]%s" % (
                story.get("id", "?"),
                story.get("state", "?"),
                (" %s" % story["title"]) if story.get("title") else "",
            ))
    elif board.admitted_units:
        # Units are admitted to the Cycle but boarded elsewhere (an integration
        # seat). Naming them is the difference between "this Cycle admitted
        # nothing" and "this clone does not hold the units".
        lines.append("Admitted Units (boarded on delivery workstreams): %s"
                     % ", ".join(board.admitted_units))
    elif board.identity.get("integration_seat"):
        # The distinction still has to survive when the ids cannot be recovered
        # (no sealed manifest yet): an empty integration board is not an empty
        # Cycle, and saying "none admitted" here would be a false statement.
        lines.append(
            "Work Units: none on this integration clone's board — units live on "
            "the delivery workstream boards. The admitted ids are only in the "
            "sealed manifest, which this Cycle does not have yet."
        )
    elif board.hydrated:
        lines.append("Work Units: none admitted to this Cycle")
    sync = sub.get("sync")
    if isinstance(sync, dict) and sync.get("verdict"):
        lines.append("Sync Verdict: %s (cycle %s)" % (
            sync.get("verdict"), sync.get("cycle")))
    lines.append(
        "SPQ resume rule: run `next_action` before planning anything. Do not "
        "replan this Cycle from memory."
    )
    return lines


def render_restore(board: Board) -> str:
    """The pipeline-state block a session restore injects. '' when there is
    nothing to say -- but a board that could NOT be read says so instead."""
    if not board.available:
        if board.layout == "none":
            return ""
        return "Build Mode: %s\nBoard unreadable: %s" % (
            board.build_mode, "; ".join(board.problems) or "unknown reason")
    out = ["Build Mode: %s" % board.build_mode]
    if board.problems:
        out.append("State problems: %s" % "; ".join(board.problems))
    if board.layout == "spq":
        out.extend(_render_spq(board))
    elif board.layout == "multi-spec":
        active = board.identity.get("active_spec") or ""
        out.append("Active Spec: %s" % (active or "<none>"))
        for label, sub in board.substates:
            out.append("")
            out.append("### Spec: %s%s" % (
                label, "  (active)" if label == active else ""))
            out.extend(_render_flat(board.build_mode, sub, prefix="  "))
    else:
        sub = board.substates[0][1] if board.substates else {}
        if "lifecycle_state" not in sub:
            # A v2 board with no lifecycle at all says nothing worth injecting;
            # preserve the previous hook's silence for that case.
            return ""
        out.extend(_render_flat(board.build_mode, sub))
    return "\n".join(out)


def render_title_suffix(board: Board) -> str:
    """The session-title suffix (' · Sprint 3', ' · Cycle 2', ...)."""
    if not board.available:
        return ""
    if board.layout == "spq":
        seq = board.identity.get("cycle_seq") or 0
        if board.hydrated and seq:
            return " · Cycle %s" % seq
        return " · %s" % str(board.lifecycle_state or "SPQ").replace("_", " ").title()
    if board.layout == "multi-spec":
        active = board.identity.get("active_spec")
        if not active:
            return ""
        for label, sub in board.substates:
            if label == str(active):
                lbl = _title_label(board.build_mode, sub)
                return " · %s%s" % (label, (" · " + lbl) if lbl else "")
        return " · %s" % active
    sub = board.substates[0][1] if board.substates else {}
    return " · %s" % _title_label(board.build_mode, sub)


def _title_label(mode: str, sub: Dict[str, Any]) -> str:
    lifecycle = str(sub.get("lifecycle_state", "INCEPTION"))
    if mode == "scrum":
        n = sub.get("current_sprint", 0)
        return ("Sprint %s" % n) if n else lifecycle.title()
    return lifecycle.replace("_", " ").title()


def main(argv: Optional[List[str]] = None) -> int:
    """CLI: pipeline_board.py <project_dir> [read|restore]

    `read`    the full Board as JSON (the debugging / scripting view).
    `restore` the session-restore projection, in a shape a hook can split
              without a second interpreter: LINE 1 is the session-title suffix
              (always exactly one line, possibly empty), and everything from
              line 2 on is the context block.
    """
    args = list(sys.argv[1:] if argv is None else argv)
    project_dir = args[0] if args else "."
    action = args[1] if len(args) > 1 else "read"
    board = read_board(project_dir)
    if action == "restore":
        suffix = render_title_suffix(board).replace("\n", " ")
        sys.stdout.write(suffix + "\n" + render_restore(board) + "\n")
    else:
        print(json.dumps(board.as_dict(), indent=2, default=str))
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
